package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.logistics.box.*;
import com.simibubi.create.content.logistics.packager.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.phys.*;

final class PackagerRenderingTest {
    private static final BlockPos P=new BlockPos(1400,4,5);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1402 8 12");context.waitFor(client->Math.abs(client.player.getX()-1402.5)<.1,300);
        var ready=new AtomicBoolean();for(int i=0;i<300&&!ready.get();i++){server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();ready.set(level.hasChunkAt(new BlockPos(1392,3,0))&&level.hasChunkAt(new BlockPos(1423,3,15)));});if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError("Packager scene chunks missing");server.runCommand("fill 1392 3 0 1423 3 15 minecraft:smooth_quartz");server.runCommand("setblock 1400 4 4 minecraft:chest");server.runCommand("setblock 1400 4 5 create:packager[facing=south]");server.runCommand("setblock 1405 4 4 minecraft:chest");server.runCommand("setblock 1405 4 5 create:repackager[facing=south]");server.runCommand("setblock 1410 4 5 create:packager[facing=up]");server.runCommand("setblock 1413 4 5 create:packager[facing=down]");server.runCommand("setblock 1399 4 5 minecraft:oak_sign");
        context.waitFor(client->client.level.getBlockEntity(P) instanceof PackagerBlockEntity&&client.level.getBlockState(new BlockPos(1400,3,10)).is(Blocks.SMOOTH_QUARTZ),300);world.getConnection().waitForChunksRender();
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((ChestBlockEntity)level.getBlockEntity(P.north())).setItem(0,new ItemStack(Items.APPLE,48));var sign=(SignBlockEntity)level.getBlockEntity(P.west());var lines=List.<Component>of(Component.literal("Output A"),Component.empty(),Component.empty(),Component.empty());sign.setText(new SignText(lines,lines,DyeColor.BLACK,false),SignTextSlot.FRONT);level.setBlockAndUpdate(P.east(),Blocks.REDSTONE_BLOCK.defaultBlockState());});
        context.waitFor(client->client.level.getBlockEntity(P) instanceof PackagerBlockEntity packager&&!packager.heldBox.isEmpty()&&!packager.animationInward,200);
        context.waitFor(client->{var packager=(PackagerBlockEntity)client.level.getBlockEntity(P);return packager.animationTicks>5&&packager.animationTicks<10;},100);
        context.runOnClient(client->{var packager=(PackagerBlockEntity)client.level.getBlockEntity(P);var extracted=client.getBlockEntityRenderDispatcher().tryExtractRenderState(packager,.5f,null,false);if(!(extracted instanceof PackagerRenderer.State state)||!state.open||state.hatch.mesh==null||state.hatch.mesh.size()==0||state.tray.mesh==null||state.tray.mesh.size()==0||state.box.isEmpty()||state.offset<=0)throw new AssertionError("Animated packager render state incomplete");if(!PackageItem.getAddress(packager.heldBox).equals("Output A"))throw new AssertionError("Sign address not synchronized");});context.getInput().lookAt(P);context.takeScreenshot("create-vulkan-packager-outbound-animation");
        context.waitFor(client->((PackagerBlockEntity)client.level.getBlockEntity(P)).animationTicks==0,100);server.runCommand("setblock 1401 4 5 minecraft:air");server.runCommand("tp @p 1400 4 9");context.waitFor(client->Math.abs(client.player.getX()-1400.5)<.1,200);server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.resetFallDistance();player.setHealth(player.getMaxHealth());player.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);});server.runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&client.player.getMainHandItem().isEmpty(),200);context.getInput().lookAt(P);context.takeScreenshot("create-vulkan-packager-ready-output");
        context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P),200);context.getInput().pressKey(options->options.keyUse);
        context.waitFor(client->PackageItem.isPackage(client.player.getMainHandItem())&&((PackagerBlockEntity)client.level.getBlockEntity(P)).heldBox.isEmpty(),200);
        context.runOnClient(client->{if(PackageItem.getContents(client.player.getMainHandItem()).getFirst().getCount()!=48)throw new AssertionError("Real packager collection lost contents");});
        // A real right click returns the packed cargo to the source inventory and starts an inward cycle.
        context.waitTicks(5);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.player.getMainHandItem().isEmpty()&&((PackagerBlockEntity)client.level.getBlockEntity(P)).animationInward&&((PackagerBlockEntity)client.level.getBlockEntity(P)).animationTicks>0,200);server.runOnServer(ignored->{var chest=(ChestBlockEntity)world.getConnection().getServerLevel().getBlockEntity(P.north());if(chest.getItem(0).getCount()!=48)throw new AssertionError("Native manual unpack duplicated or lost apples");});
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var target=P.east(5).north();var chest=(ChestBlockEntity)level.getBlockEntity(target);var first=PackageItem.containing(List.of(new ItemStack(Items.DIAMOND,40)));var second=PackageItem.containing(List.of(new ItemStack(Items.DIAMOND,30)));PackageItem.setOrder(first,91,0,true,0,false,null);PackageItem.setOrder(second,91,0,true,1,true,null);chest.setItem(0,first);chest.setItem(1,second);level.setBlockAndUpdate(P.east(6),Blocks.REDSTONE_BLOCK.defaultBlockState());});
        context.waitFor(client->client.level.getBlockEntity(P.east(5)) instanceof PackagerBlockEntity repackager&&!repackager.heldBox.isEmpty()&&repackager.animationTicks==0,200);
        context.runOnClient(client->{var repackager=(PackagerBlockEntity)client.level.getBlockEntity(P.east(5));int diamonds=PackageItem.getContents(repackager.heldBox).stream().filter(item->item.is(Items.DIAMOND)).mapToInt(ItemStack::getCount).sum();if(diamonds!=70)throw new AssertionError("Repackager visual lost fragment contents");});
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 1406 8 12");context.waitFor(client->Math.abs(client.player.getX()-1406.5)<.1,200);context.getInput().lookAt(new BlockPos(1406,4,5));world.getConnection().waitForChunksRender();context.runOnClient(client->{for(var pos:List.of(P,P.east(5),P.east(10),P.east(13))){var be=client.level.getBlockEntity(pos);var rendered=client.getBlockEntityRenderDispatcher().tryExtractRenderState(be,.5f,null,false);if(!(rendered instanceof PackagerRenderer.State state)||state.hatch.mesh==null||state.tray.mesh==null)throw new AssertionError("Packager orientation render missing");}});context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot("create-vulkan-packager-orientations");
        var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);chunkUnload(context,world);
    }
    private static void chunkUnload(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();var pos=new BlockPos(1456,4,5);var target=pos.west();server.runCommand("tp @p 1456 8 12");context.waitFor(client->Math.abs(client.player.getX()-1456.5)<.1,300);var ready=new AtomicBoolean();for(int i=0;i<300&&!ready.get();i++){server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();ready.set(level.hasChunkAt(target)&&level.hasChunkAt(pos));});if(!ready.get())context.waitTicks(1);}if(!ready.get())throw new AssertionError("Boundary scene not loaded");server.runCommand("setblock 1455 4 5 minecraft:chest");server.runCommand("setblock 1456 4 5 create:packager[facing=east]");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((ChestBlockEntity)level.getBlockEntity(target)).setItem(0,new ItemStack(Items.DIAMOND,17));((PackagerBlockEntity)level.getBlockEntity(pos)).heldBox=PackageItem.containing(List.of(new ItemStack(Items.STONE)));level.getChunkSource().addTicket(new net.minecraft.server.level.Ticket(net.minecraft.server.level.TicketType.FORCED,33),new net.minecraft.world.level.ChunkPos(pos.getX()>>4,pos.getZ()>>4));});server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();for(int i=0;i<120&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var packager=(PackagerBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,pos);if(packager!=null){packager.getAvailableItems();packager.attemptToSend(null);}unloaded.set(!level.isLoaded(target));});}if(!unloaded.get())throw new AssertionError("Packager lookup kept target chunk loaded");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var packager=(PackagerBlockEntity)com.simibubi.create.foundation.utility.LoadedLevelAccess.blockEntity(level,pos);packager.clearContent();for(int i=0;i<100;i++){packager.getAvailableItems();packager.attemptToSend(null);}if(!packager.heldBox.isEmpty()||level.isLoaded(target))throw new AssertionError("Packager loaded or extracted from unloaded target");});
        server.runCommand("tp @p 1456 8 12");context.waitFor(client->Math.abs(client.player.getX()-1456.5)<.1&&client.level.getBlockEntity(target) instanceof ChestBlockEntity,400);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var packager=(PackagerBlockEntity)level.getBlockEntity(pos);var chest=(ChestBlockEntity)level.getBlockEntity(target);if(chest.getItem(0).getCount()!=17)throw new AssertionError("Unloaded inventory lost contents");packager.attemptToSend(null);if(PackageItem.getContents(packager.heldBox).getFirst().getCount()!=17)throw new AssertionError("Packager did not recover after target return");level.getChunkSource().removeTicketWithRadius(net.minecraft.server.level.TicketType.FORCED,new net.minecraft.world.level.ChunkPos(pos.getX()>>4,pos.getZ()>>4),0);});
    }
}
